// Zen prefs from frameshell, read on every start. Generated by frame theme from
// themes/<theme>.json; edit themes/templates/zen/user.js instead.

// Load chrome/userChrome.css (off by default)
user_pref("toolkit.legacyUserProfileCustomizations.stylesheets", true);

// {{name}}: accent, dark windows, square corners like the rest of the desktop
user_pref("zen.theme.accent-color", "{{colors.primary}}");
user_pref("zen.view.window.scheme", 0);
user_pref("zen.theme.border-radius", 0);
user_pref("zen.theme.content-element-separation", 8);

user_pref("zen.welcome-screen.seen", true);
user_pref("zen.watermark.enabled", false);
